package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.JsonCreator;
import com.fasterxml.jackson.annotation.JsonIgnoreProperties;
import com.fasterxml.jackson.core.JsonLocation;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.cfg.DeserializerFactoryConfig;
import com.fasterxml.jackson.databind.cfg.HandlerInstantiator;
import com.fasterxml.jackson.databind.deser.impl.CreatorCollector;
import com.fasterxml.jackson.databind.deser.impl.StdKeyDeserializers;
import com.fasterxml.jackson.databind.deser.std.*;
import com.fasterxml.jackson.databind.ext.OptionalHandlerFactory;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.jsontype.NamedType;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeResolverBuilder;
import com.fasterxml.jackson.databind.type.*;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.*;
import java.io.*;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class BasicDeserializerFactory_createKeyDeserializer_TriageGen2Test {

    private DeserializationContext ctxt;
    private DeserializationConfig config;
    private TypeFactory typeFactory;
    private DeserializerFactoryConfig factoryConfig;
    private BasicDeserializerFactory factory;

    // Concrete implementation for testing abstract class
    private static class TestBasicDeserializerFactory extends BasicDeserializerFactory {
        protected TestBasicDeserializerFactory(DeserializerFactoryConfig config) {
            super(config);
        }

        @Override
        protected DeserializerFactory withConfig(DeserializerFactoryConfig config) {
            return new TestBasicDeserializerFactory(config);
        }

        @Override
        public KeyDeserializer _createEnumKeyDeserializer(DeserializationContext ctxt, JavaType type) {
            return mock(KeyDeserializer.class);
        }
    }

    // Mock implementation of DeserializerFactoryConfig to control the factory behavior
    private static class MockFactoryConfig implements DeserializerFactoryConfig {
        private KeyDeserializers keyDeserializers;
        private BeanDeserializerModifier modifier;

        @Override
        public boolean hasKeyDeserializers() {
            return keyDeserializers != null;
        }

        @Override
        public KeyDeserializers keyDeserializers() {
            return keyDeserializers;
        }

        @Override
        public boolean hasDeserializerModifiers() {
            return modifier != null;
        }

        @Override
        public Iterable<BeanDeserializerModifier> deserializerModifiers() {
            return modifier != null ? Collections.singleton(modifier) : Collections.emptyList();
        }

        // Unused methods for this test case
        @Override public boolean hasAbstractTypeResolver() { return false; }
        @Override public AbstractTypeResolver getAbstractTypeResolver() { return null; }
        @Override public boolean hasValueInstantiators() { return false; }
        @Override public ValueInstantiators getValueInstantiators() { return null; }
    }

    @Before
    public void setUp() {
        ctxt = mock(DeserializationContext.class);
        config = mock(DeserializationConfig.class);
        typeFactory = TypeFactory.defaultInstance();
        factoryConfig = mock(MockFactoryConfig.class);

        when(ctxt.getConfig()).thenReturn(config);
        factory = new TestBasicDeserializerFactory(factoryConfig);
    }

    @Test
    public void testCreateKeyDeserializer_WithCustomKeyDeserializerFound() throws JsonMappingException {
        JavaType type = typeFactory.constructType(String.class);
        KeyDeserializer mockDeser = mock(KeyDeserializer.class);
        KeyDeserializers keyDeserializers = mock(KeyDeserializers.class);

        when(factoryConfig.hasKeyDeserializers()).thenReturn(true);
        when(factoryConfig.keyDeserializers()).thenReturn(keyDeserializers);
        when(keyDeserializers.findKeyDeserializer(eq(type), eq(config), any(BeanDescription.class)))
                .thenReturn(mockDeser);

        KeyDeserializer result = factory.createKeyDeserializer(ctxt, type);

        assertNotNull(result);
        assertEquals(mockDeser, result);
        verify(keyDeserializers).findKeyDeserializer(eq(type), eq(config), any(BeanDescription.class));
    }

    @Test
    public void testCreateKeyDeserializer_WithCustomKeyDeserializerNotFound_FallbackToEnum() throws JsonMappingException {
        enum TestEnum { A, B }
        JavaType type = typeFactory.constructType(TestEnum.class);

        when(factoryConfig.hasKeyDeserializers()).thenReturn(true);
        KeyDeserializers keyDeserializers = mock(KeyDeserializers.class);
        when(factoryConfig.keyDeserializers()).thenReturn(keyDeserializers);
        when(keyDeserializers.findKeyDeserializer(any(), any(), any())).thenReturn(null);

        // The method _createEnumKeyDeserializer is overridden in our test class to return a mock
        KeyDeserializer result = factory.createKeyDeserializer(ctxt, type);

        assertNotNull(result);
        // Since it's an Enum, it should have triggered _createEnumKeyDeserializer
    }

    @Test
    public void testCreateKeyDeserializer_WithCustomKeyDeserializerNotFound_FallbackToStringBased() throws JsonMappingException {
        // Use a non-enum class
        JavaType type = typeFactory.constructType(Integer.class);

        when(factoryConfig.hasKeyDeserializers()).thenReturn(true);
        KeyDeserializers keyDeserializers = mock(KeyDeserializers.class);
        when(factoryConfig.keyDeserializers()).thenReturn(keyDeserializers);
        when(keyDeserializers.findKeyDeserializer(any(), any(), any())).thenReturn(null);

        // StdKeyDeserializers.findStringBasedKeyDeserializer will return null for Integer
        KeyDeserializer result = factory.createKeyDeserializer(ctxt, type);

        assertNull(result);
    }

    @Test
    public void testCreateKeyDeserializer_WithModifier() throws JsonMappingException {
        JavaType type = typeFactory.constructType(String.class);
        KeyDeserializer originalDeser = mock(KeyDeserializer.class);
        KeyDeserializer modifiedDeser = mock(KeyDeserializer.class);
        BeanDeserializerModifier modifier = mock(BeanDeserializerModifier.class);

        // Setup: No custom key deserializers in factory, so it goes to StdKeyDeserializers
        // To ensure we get a non-null 'deser' for the modifier block, we'll mock the registry
        KeyDeserializers keyDeserializers = mock(KeyDeserializers.class);
        when(factoryConfig.hasKeyDeserializers()).thenReturn(true);
        when(factoryConfig.keyDeserializers()).thenReturn(keyDeserializers);
        when(keyDeserializers.findKeyDeserializer(any(), any(), any())).thenReturn(originalDeser);

        // Setup: Modifier
        when(factoryConfig.hasDeserializerModifiers()).thenReturn(true);
        when(factoryConfig.deserializerModifiers()).thenReturn(Collections.singleton(modifier));
        when(modifier.modifyKeyDeserializer(eq(config), eq(type), eq(originalDeser))).thenReturn(modifiedDeser);

        KeyDeserializer result = factory.createKeyDeserializer(ctxt, type);

        assertNotNull(result);
        assertEquals(modifiedDeser, result);
        verify(modifier).modifyKeyDeserializer(config, type, originalDeser);
    }

    @Test
    public void testCreateKeyDeserializer_NoKeyDeserializersAndNoModifier() throws JsonMappingException {
        JavaType type = typeFactory.constructType(String.class);

        when(factoryConfig.hasKeyDeserializers()).thenReturn(false);
        when(factoryConfig.hasDeserializerModifiers()).thenReturn(false);

        // For String, StdKeyDeserializers.findStringBasedKeyDeserializer returns a default one
        KeyDeserializer result = factory.createKeyDeserializer(ctxt, type);

        assertNotNull(result);
    }

    @Test
    public void testCreateKeyDeserializer_EmptyRegistry() throws JsonMappingException {
        JavaType type = typeFactory.constructType(String.class);

        when(factoryConfig.hasKeyDeserializers()).thenReturn(true);
        KeyDeserializers keyDeserializers = mock(KeyDeserializers.class);
        when(factoryConfig.keyDeserializers()).thenReturn(keyDeserializers);
        when(keyDeserializers.findKeyDeserializer(any(), any(), any())).thenReturn(null);

        // Ensure it doesn't crash and follows fallback
        KeyDeserializer result = factory.createKeyDeserializer(ctxt, type);
        assertNotNull(result);
    }
}
